// SIMULATED data only. Generated by a seeded random function so the dashboard has something to show.
// These numbers are NOT campaign results and NOT forecasts. They exist to demonstrate the dashboard.

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const DAY = 86400000;
const VISITS_PER_DAY = [210, 270, 250, 300, 260]; // a "Day 5 snapshot" of a week
// share of visits by source, per day (remainder = direct)
const MIX = [
  { src: ['wa_outcome', 'wa_career', 'wa_lowbar'], w: [0.40, 0.36, 0.30, 0.26, 0.22], conv: 0.27 },
  { src: ['reel'], w: [0.10, 0.14, 0.16, 0.18, 0.18], conv: 0.19 },
  { src: ['boost'], w: [0, 0, 0.08, 0.14, 0.16], conv: 0.21 },
  { src: ['reddit', 'discord', 'linkedin'], w: [0.20, 0.22, 0.20, 0.16, 0.14], conv: 0.17 },
  { src: ['share_squad', 'share_plain'], w: [0.02, 0.08, 0.18, 0.22, 0.26], conv: 0.36, ref: true },
];

export function generateSample(seed = 42) {
  const rnd = mulberry32(seed);
  const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
  const refPool = ['SMP-4K7', 'SMP-9QX', 'SMP-2MD', 'SMP-7TA', 'SMP-5HW', 'SMP-8CZ', 'SMP-3NB', 'SMP-6RF'];
  const t0 = Date.UTC(2026, 0, 5, 4, 0, 0);
  const events = [];

  VISITS_PER_DAY.forEach((n, day) => {
    for (let i = 0; i < n; i += 1) {
      // choose source by weighted mix
      let roll = rnd();
      let chosen = null;
      for (const m of MIX) {
        roll -= m.w[day];
        if (roll < 0) { chosen = m; break; }
      }
      const m = chosen || { src: ['direct'], conv: 0.15 };
      let src = pick(m.src);
      if (src === 'share_squad' && rnd() > 0.6) src = 'share_plain'; // squad gets ~60% of referral visits
      const ref = src === 'share_squad' ? pick(refPool) : '';
      const variant = rnd() < 0.5 ? 'A' : 'B';
      const conv = m.conv * (variant === 'B' ? 1.1 : 1);
      const ts = t0 + day * DAY + Math.floor(rnd() * 14 * 3600000);
      const base = { ts, day, src, ref, variant, simulated: true };
      events.push({ ...base, type: 'visit' });
      if (ref) events.push({ ...base, type: 'referral_opened' });
      const pStart = Math.min(0.92, conv * 1.4);
      if (rnd() < pStart) {
        events.push({ ...base, type: 'form_started' });
        if (rnd() < conv / pStart) {
          const shareVariant = rnd() < 0.5 ? 'squad' : 'plain';
          events.push({ ...base, type: 'registered', shareVariant });
          if (rnd() < (shareVariant === 'squad' ? 0.55 : 0.3)) {
            events.push({ ...base, type: 'share_clicked', shareVariant });
          }
        }
      }
    }
  });
  return events;
}
